/**
 * Backblaze B2 upload adapter speaking the S3-compatible API with
 * AWS Signature V4 signing via WebCrypto (Workers compatible).
 */

export class B2ConfigError extends Error {
  constructor(message = "B2 is not configured") {
    super(message);
    this.name = "B2ConfigError";
  }
}

export interface B2Env {
  B2_KEY_ID?: string;
  B2_APP_KEY?: string;
  B2_ENDPOINT: string;
  B2_BUCKET: string;
}

type FetchLike = typeof fetch;

const defaultFetch: FetchLike = (input, init) => fetch(input, init);

let fetchImpl: FetchLike = defaultFetch;

/** Inject a fetch implementation (e.g. a test stub). Pass null to restore. */
export function setB2Fetch(fn: FetchLike | null): void {
  fetchImpl = fn ?? defaultFetch;
}

async function sha256Hex(data: Uint8Array): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", data);
  return toHex(new Uint8Array(digest));
}

function toHex(bytes: Uint8Array): string {
  let out = "";
  for (const b of bytes) {
    out += b.toString(16).padStart(2, "0");
  }
  return out;
}

async function hmac(key: Uint8Array | string, data: string): Promise<Uint8Array> {
  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    typeof key === "string" ? new TextEncoder().encode(key) : key,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign(
    "HMAC",
    cryptoKey,
    new TextEncoder().encode(data),
  );
  return new Uint8Array(sig);
}

function regionFromEndpoint(endpoint: string): string {
  try {
    const host = new URL(endpoint).hostname;
    const m = host.match(/^s3\.([a-z0-9-]+)\.backblazeb2\.com$/);
    if (m?.[1]) return m[1];
  } catch {
    // fall through to default region
  }
  return "us-west-004";
}

function amzDateFormat(now: Date): string {
  const p = (n: number) => n.toString().padStart(2, "0");
  return (
    `${now.getUTCFullYear()}${p(now.getUTCMonth() + 1)}${p(now.getUTCDate())}` +
    `T${p(now.getUTCHours())}${p(now.getUTCMinutes())}${p(now.getUTCSeconds())}Z`
  );
}

export async function uploadPhoto(
  env: B2Env,
  key: string,
  body: Uint8Array,
  contentType: string,
  opts?: { now?: Date },
): Promise<{ photo_url: string }> {
  const keyId = env.B2_KEY_ID;
  const appKey = env.B2_APP_KEY;
  if (!keyId || !appKey) {
    throw new B2ConfigError();
  }

  const endpoint = env.B2_ENDPOINT.replace(/\/+$/, "");
  const bucket = env.B2_BUCKET;
  const url = `${endpoint}/${bucket}/${key}`;
  const host = new URL(url).host;
  const region = regionFromEndpoint(endpoint);

  const now = opts?.now ?? new Date();
  const amzDate = amzDateFormat(now);
  const dateStamp = amzDate.slice(0, 8);
  const payloadHash = await sha256Hex(body);

  // Canonical request (headers already in sorted order).
  const canonicalRequest = [
    "PUT",
    `/${bucket}/${key}`,
    "",
    `content-type:${contentType}`,
    `host:${host}`,
    `x-amz-content-sha256:${payloadHash}`,
    `x-amz-date:${amzDate}`,
    "",
    "content-type;host;x-amz-content-sha256;x-amz-date",
    payloadHash,
  ].join("\n");

  const scope = `${dateStamp}/${region}/s3/aws4_request`;
  const canonicalRequestHash = await sha256Hex(new TextEncoder().encode(canonicalRequest));
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    scope,
    canonicalRequestHash,
  ].join("\n");

  // Signing key chain: AWS4<secret> -> date -> region -> s3 -> aws4_request.
  let signingKey = await hmac(`AWS4${appKey}`, dateStamp);
  signingKey = await hmac(signingKey, region);
  signingKey = await hmac(signingKey, "s3");
  signingKey = await hmac(signingKey, "aws4_request");
  const signature = toHex(await hmac(signingKey, stringToSign));

  const authorization =
    `AWS4-HMAC-SHA256 Credential=${keyId}/${scope}, ` +
    `SignedHeaders=content-type;host;x-amz-content-sha256;x-amz-date, ` +
    `Signature=${signature}`;

  await fetchImpl(url, {
    method: "PUT",
    headers: {
      "content-type": contentType,
      host,
      "x-amz-content-sha256": payloadHash,
      "x-amz-date": amzDate,
      authorization,
    },
    body,
  });

  return { photo_url: url };
}

export type { KinshipGraph, KinshipPerson, KinshipCouple, KinshipChildOf, ClassifyResult, EdgeKind, TermRow } from './types';
export { classify } from './classify';
export { TERMS, KIN_TERM_ROWS, resolveTerms } from './terms';

export interface KinshipPerson {
  id: string;
  gender: 'm' | 'f' | 'o';
  dob?: string | null;
  birth_order?: number | null;
}

export interface KinshipCouple {
  couple_id: string;
  partner_a?: string | null;
  partner_b?: string | null;
}

export interface KinshipChildOf {
  couple_id: string;
  child_person_id: string;
}

/** The graph shape the server loads from D1 (person/couple/child_of). */
export interface KinshipGraph {
  persons: KinshipPerson[];
  couples: KinshipCouple[];
  child_of: KinshipChildOf[];
}

export type EdgeKind = 'up' | 'sp' | 'down';

export interface ClassifyResult {
  /** canonical relation key, or null when the shape is unknown */
  relation_key: string | null;
  /** edge tokens of the path that was found ('up' | 'sp' | 'down') */
  path: EdgeKind[];
}

export interface TermRow {
  term: string;
  gloss: string;
}

import type { ClassifyResult, EdgeKind, KinshipGraph } from './types';
import { buildAdjacency, genderOf, olderThan, type Adjacency } from './graph';

interface BfsNode {
  id: string;
  /** person ids from start (inclusive) to this node */
  chain: string[];
  edges: EdgeKind[];
}

/**
 * BFS over family edges from `fromId` to `toId`.
 * Neighbor kinds are explored in canonical order up < sp < down so the
 * shortest path found is deterministic. Max depth 6 keeps this linear-ish.
 * Returns the goal node carrying the FULL identity chain - tokens alone are
 * ambiguous when several same-kind neighbors exist (e.g. two parents).
 */
function bfs(adj: Adjacency, fromId: string, toId: string): BfsNode | null {
  if (fromId === toId) return { id: fromId, chain: [fromId], edges: [] };
  const visited = new Set<string>([fromId]);
  let frontier: BfsNode[] = [{ id: fromId, chain: [fromId], edges: [] }];
  for (let depth = 0; depth < 6; depth++) {
    const next: BfsNode[] = [];
    for (const node of frontier) {
      const expand = (kind: EdgeKind, ids: string[] | undefined): BfsNode | null => {
        for (const id of ids ?? []) {
          if (id === toId) {
            return { id, chain: [...node.chain, id], edges: [...node.edges, kind] };
          }
          if (visited.has(id)) continue;
          visited.add(id);
          next.push({ id, chain: [...node.chain, id], edges: [...node.edges, kind] });
        }
        return null;
      };
      // canonical order: up, sp, down
      const hit = expand('up', adj.parents.get(node.id))
        ?? expand('sp', adj.spouses.get(node.id))
        ?? expand('down', adj.children.get(node.id));
      if (hit) return hit;
    }
    frontier = next;
  }
  return null;
}

function baseParentalSiblingKey(
  adj: Adjacency,
  linkingParentId: string,
  targetId: string,
): string | null {
  const lpGender = genderOf(adj, linkingParentId);
  const tGender = genderOf(adj, targetId);
  if (!tGender) return null;
  if (lpGender === 'm') {
    // paternal side: linking parent is the father
    if (tGender === 'm') return olderThan(adj, targetId, linkingParentId) ? 'fa_br_el' : 'fa_br_yo';
    return 'fa_si';
  }
  if (lpGender === 'f') {
    // maternal side: linking parent is the mother
    if (tGender === 'm') return 'mo_br';
    return olderThan(adj, targetId, linkingParentId) ? 'mo_si_el' : 'mo_si_yo';
  }
  return null;
}

const SPOUSE_KEY_OF_BASE: Record<string, string> = {
  fa_br_el: 'fa_br_el_sp',
  fa_br_yo: 'fa_br_yo_sp',
  fa_si: 'fa_si_sp',
  mo_br: 'mo_br_sp',
  mo_si_el: 'mo_si_sp', // mother's-sisters collapse to one spouse key
  mo_si_yo: 'mo_si_sp',
};

function keyFromPath(adj: Adjacency, fromId: string, path: EdgeKind[], targets: string[]): string | null {
  // targets[i] = person at the FAR end of path edge i
  const g = (offset: number) => genderOf(adj, targets[offset]!);

  switch (path.length) {
    case 0:
      return 'self';
    case 1: {
      if (path[0] === 'sp') return 'spouse';
      if (path[0] === 'up') return g(0) === 'm' ? 'fa' : g(0) === 'f' ? 'mo' : null;
      if (path[0] === 'down') return g(0) === 'm' ? 'son' : g(0) === 'f' ? 'daughter' : null;
      return null;
    }
    case 2: {
      if (path[0] === 'up' && path[1] === 'up') {
        // grandparent: paternal when the nearer ancestor is the father
        const nearIsMale = g(0) === 'm';
        const far = g(1);
        if (nearIsMale) return far === 'm' ? 'grandfa_pat' : far === 'f' ? 'grandmo_pat' : null;
        return far === 'm' ? 'grandfa_mat' : far === 'f' ? 'grandmo_mat' : null;
      }
      if (path[0] === 'up' && path[1] === 'down') {
        // full sibling via shared parent
        const sib = g(1);
        const younger = !olderThan(adj, targets[1]!, fromId); // default younger when unknown
        if (sib === 'm') return younger ? 'brother_yo' : 'brother_el';
        if (sib === 'f') return younger ? 'sister_yo' : 'sister_el';
        return null;
      }
      if (path[0] === 'down' && path[1] === 'down') {
        // grandchild: gender of the FINAL child decides
        return g(1) === 'm' ? 'grandson' : g(1) === 'f' ? 'granddaughter' : null;
      }
      if (path[0] === 'down' && path[1] === 'sp') {
        return g(0) === 'm' ? 'son_sp' : g(0) === 'f' ? 'da_sp' : null;
      }
      return null;
    }
    case 3: {
      if (path[0] === 'up' && path[1] === 'up' && path[2] === 'down') {
        return baseParentalSiblingKey(adj, targets[0]!, targets[2]!);
      }
      if (path[0] === 'up' && path[1] === 'down' && path[2] === 'down') {
        // sibling's child: nodes[1] is the sibling, nodes[2] the child
        const sib = g(1);
        const child = g(2);
        if (sib === 'm') return child === 'm' ? 'brother_son' : child === 'f' ? 'brother_daughter' : null;
        if (sib === 'f') return child === 'm' ? 'sister_son' : child === 'f' ? 'sister_daughter' : null;
        return null;
      }
      return null;
    }
    case 4: {
      if (
        path[0] === 'up' && path[1] === 'up' && path[2] === 'down' && path[3] === 'sp'
      ) {
        const base = baseParentalSiblingKey(adj, targets[0]!, targets[2]!);
        return base ? SPOUSE_KEY_OF_BASE[base] ?? null : null;
      }
      if (
        path[0] === 'up' && path[1] === 'up' && path[2] === 'down' && path[3] === 'down'
      ) {
        return 'cousin';
      }
      return null;
    }
    default:
      return null;
  }
}

/**
 * Compute the canonical relation between two persons.
 * Returns relation_key null when the shape is unknown (step relations,
 * spouse-side chains, disconnected people).
 */
export function classify(graph: KinshipGraph, fromId: string, toId: string): ClassifyResult {
  const adj = buildAdjacency(graph);
  const goal = bfs(adj, fromId, toId);
  if (!goal) return { relation_key: null, path: [] };
  // targets[i] is the person reached after traversing goal.edges[i]
  const targets = goal.chain.slice(1);
  return { relation_key: keyFromPath(adj, fromId, goal.edges, targets), path: goal.edges };
}

import type { KinshipGraph } from './types';

export interface Adjacency {
  // child id -> parent ids
  parents: Map<string, string[]>;
  // parent id -> child ids
  children: Map<string, string[]>;
  // spouse edges (both directions)
  spouses: Map<string, string[]>;
  personById: Map<string, { gender: 'm' | 'f' | 'o'; dob: string | null; birth_order: number | null }>;
}

function push(map: Map<string, string[]>, k: string, v: string): void {
  const arr = map.get(k);
  if (!arr) map.set(k, [v]);
  else if (!arr.includes(v)) arr.push(v);
}

export function buildAdjacency(g: KinshipGraph): Adjacency {
  const parents = new Map<string, string[]>();
  const children = new Map<string, string[]>();
  const spouses = new Map<string, string[]>();
  const personById = new Map<string, { gender: 'm' | 'f' | 'o'; dob: string | null; birth_order: number | null }>();

  for (const p of g.persons) {
    personById.set(p.id, { gender: p.gender, dob: p.dob ?? null, birth_order: p.birth_order ?? null });
  }

  const coupleById = new Map(g.couples.map(c => [c.couple_id, c]));

  for (const c of g.couples) {
    if (c.partner_a && c.partner_b) {
      push(spouses, c.partner_a, c.partner_b);
      push(spouses, c.partner_b, c.partner_a);
    }
  }
  for (const co of g.child_of) {
    const couple = coupleById.get(co.couple_id);
    if (!couple) continue;
    for (const pid of [couple.partner_a, couple.partner_b]) {
      if (pid) push(parents, co.child_person_id, pid);
    }
    if (couple.partner_a) push(children, couple.partner_a, co.child_person_id);
    if (couple.partner_b) push(children, couple.partner_b, co.child_person_id);
  }

  return { parents, children, spouses, personById };
}

export function genderOf(adj: Adjacency, id: string): 'm' | 'f' | 'o' | null {
  return adj.personById.get(id)?.gender ?? null;
}

/** true when x is demonstrably older than y (dob, fallback birth_order). */
export function olderThan(adj: Adjacency, x: string, y: string): boolean {
  const px = adj.personById.get(x);
  const py = adj.personById.get(y);
  if (!px || !py) return false;
  if (px.dob && py.dob && px.dob !== py.dob) return px.dob < py.dob;
  if (px.birth_order != null && py.birth_order != null && px.birth_order !== py.birth_order) {
    return px.birth_order < py.birth_order;
  }
  return false; // unknown ordering defaults to "younger" at call sites (documented choice)
}

